from pathlib import Path
from datetime import datetime
import hashlib
import re
import shutil

ROOT = Path(__file__).resolve().parent
HTML = ROOT / "static" / "index.html"
MAIN = ROOT / "app" / "main.py"

if not HTML.exists():
    raise SystemExit("ERROR: static/index.html not found. Run this script from your src directory.")

s = HTML.read_text(encoding="utf-8")

# Guard against applying Stage 2 twice.
if "PP_IMAGE_STUDIO_2_0_STAGE2_CSS" in s or "Professional Image Editor 2.0" in s:
    raise SystemExit("ERROR: Image Studio 2.0 Stage 2 already appears to be applied.")

css_start = s.index('<style id="PP_IMAGE_STUDIO_2_0_CSS">')
css_end = s.index('</style>', css_start) + len('</style>')
html_section = s.index('<section id="imagestudio"')
html_start = s.index('  <!-- EDITOR -->', html_section)
html_end = s.index('  <!-- EXISTING RESIZE -->', html_start)
js_start = s.index('let ppImgCanvas = null;')
js_end = s.index('function imageFiles()', js_start)

STAGE2_CSS = '\n<style id="PP_IMAGE_STUDIO_2_0_STAGE2_CSS">\n.pp-imgstudio-stage2{display:grid;grid-template-columns:260px minmax(420px,1fr);gap:14px}\n.pp-imgstudio-stage2-tools{background:#fff;border:1px solid #e4e7ef;border-radius:14px;padding:14px;max-height:760px;overflow:auto}\n.pp-imgstudio-stage2-tools .tool-section{padding-bottom:13px;margin-bottom:13px;border-bottom:1px solid #edf0f5}\n.pp-imgstudio-stage2-tools .tool-section:last-child{border-bottom:0;margin-bottom:0}\n.pp-imgstudio-stage2-tools h4{margin:0 0 9px;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#667085}\n.pp-img-tool-row{display:grid;grid-template-columns:1fr 1fr;gap:7px}\n.pp-img-tool-row button{border:1px solid #dfe3eb;background:#f8fafc;border-radius:8px;padding:8px;cursor:pointer;font-weight:700;color:#344054}\n.pp-img-tool-row button:hover{background:#eef2ff;border-color:#c7d2fe}\n.pp-img-tool-row button.active{background:#4f46e5;color:#fff;border-color:#4f46e5}\n.pp-img-field{margin-top:8px}\n.pp-img-field label{display:block;font-size:11px;font-weight:750;color:#475467;margin-bottom:4px}\n.pp-img-field input,.pp-img-field select{width:100%;padding:8px;border:1px solid #d0d5dd;border-radius:8px;background:#fff}\n.pp-img-field input[type=color]{padding:2px;height:36px}\n.pp-img-field input[type=range]{padding:0}\n.pp-img-field output{float:right;font-size:10px;color:#667085}\n.pp-img-small-note{font-size:10px;color:#667085;line-height:1.4;margin-top:6px}\n.pp-img-crop-ratios{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}\n.pp-img-crop-ratios button{font-size:10px;padding:7px 4px}\n.pp-img-editor-canvas-stage{position:relative;min-width:0;background:#111827;border-radius:14px;overflow:hidden}\n.pp-img-editor-canvas-stage .pp-img-canvas-area{border-radius:0}\n.pp-img-crop-box{position:absolute;display:none;border:2px solid #fff;box-shadow:0 0 0 9999px rgba(0,0,0,.58);pointer-events:none;z-index:4}\n.pp-img-crop-box:before,.pp-img-crop-box:after{content:"";position:absolute;inset:33.333% 0;border-top:1px dashed rgba(255,255,255,.45);border-bottom:1px dashed rgba(255,255,255,.45)}\n.pp-img-crop-box:after{inset:0 33.333%;border-left:1px dashed rgba(255,255,255,.45);border-right:1px dashed rgba(255,255,255,.45)}\n.pp-img-object-hint{margin-top:8px;padding:8px;border-radius:8px;background:#f5f3ff;color:#4c1d95;font-size:10px;line-height:1.45}\n.pp-img-border-preview{height:38px;border-radius:8px;background:#111827;border:8px solid #fff}\n.pp-img-quick-actions{display:flex;gap:6px;flex-wrap:wrap}\n.pp-img-quick-actions button{flex:1;min-width:90px}\n@media(max-width:1100px){.pp-imgstudio-stage2{grid-template-columns:1fr}.pp-imgstudio-stage2-tools{max-height:none}}\n@media(max-width:650px){.pp-img-tool-row{grid-template-columns:1fr 1fr}.pp-img-crop-ratios{grid-template-columns:repeat(3,1fr)}}\n</style>\n'
STAGE2_HTML = '  <!-- EDITOR -->\n  <div id="ppImgEditor" class="pp-img-panel">\n\n    <div class="pp-img-upload-card">\n      <div>\n        <b>Professional Image Editor 2.0</b>\n        <div class="note">Edit locally in your browser — crop, text, shapes, drawing, watermark, adjustments and filters.</div>\n      </div>\n      <label class="pp-img-file-btn">\n        Choose image\n        <input id="ppImgEditorFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/bmp,image/tiff">\n      </label>\n    </div>\n\n    <div class="pp-imgstudio-stage2">\n      <aside class="pp-imgstudio-stage2-tools">\n\n        <div class="tool-section">\n          <h4>Transform</h4>\n          <div class="pp-img-tool-row">\n            <button onclick="ppImgRotate(-90)">↶ 90°</button>\n            <button onclick="ppImgRotate(90)">↷ 90°</button>\n            <button onclick="ppImgRotate(180)">180°</button>\n            <button onclick="ppImgFlip(\'h\')">↔ Flip H</button>\n            <button onclick="ppImgFlip(\'v\')">↕ Flip V</button>\n            <button onclick="ppImgReset()">Reset</button>\n          </div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Crop Studio</h4>\n          <div class="pp-img-crop-ratios">\n            <button onclick="ppImgSetCropRatio(\'free\')">Free</button>\n            <button onclick="ppImgSetCropRatio(\'1:1\')">1:1</button>\n            <button onclick="ppImgSetCropRatio(\'4:3\')">4:3</button>\n            <button onclick="ppImgSetCropRatio(\'3:2\')">3:2</button>\n            <button onclick="ppImgSetCropRatio(\'16:9\')">16:9</button>\n            <button onclick="ppImgSetCropRatio(\'9:16\')">9:16</button>\n            <button onclick="ppImgSetCropRatio(\'4:5\')">4:5</button>\n            <button onclick="ppImgCropCancel()">Cancel</button>\n            <button onclick="ppImgApplyCrop()">Apply</button>\n          </div>\n          <div class="pp-img-small-note">Choose a ratio, then drag on the image. Crop is applied to the current edited image.</div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Adjustments</h4>\n          <div class="pp-img-field">Brightness <output id="ppImgBrightnessOut">0</output>\n            <input id="ppImgBrightness" type="range" min="-100" max="100" value="0" oninput="ppImgApplyAdjustments()">\n          </div>\n          <div class="pp-img-field">Contrast <output id="ppImgContrastOut">0</output>\n            <input id="ppImgContrast" type="range" min="-100" max="100" value="0" oninput="ppImgApplyAdjustments()">\n          </div>\n          <div class="pp-img-field">Saturation <output id="ppImgSaturationOut">0</output>\n            <input id="ppImgSaturation" type="range" min="-100" max="100" value="0" oninput="ppImgApplyAdjustments()">\n          </div>\n          <div class="pp-img-field">Blur <output id="ppImgBlurOut">0</output>\n            <input id="ppImgBlur" type="range" min="0" max="12" value="0" oninput="ppImgApplyAdjustments()">\n          </div>\n          <div class="pp-img-field">Sepia <output id="ppImgSepiaOut">0</output>\n            <input id="ppImgSepia" type="range" min="0" max="100" value="0" oninput="ppImgApplyAdjustments()">\n          </div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Filters</h4>\n          <div class="pp-img-filter-grid">\n            <button onclick="ppImgFilter(\'normal\')">Original</button>\n            <button onclick="ppImgFilter(\'grayscale\')">B&W</button>\n            <button onclick="ppImgFilter(\'sepia\')">Sepia</button>\n            <button onclick="ppImgFilter(\'vintage\')">Vintage</button>\n            <button onclick="ppImgFilter(\'warm\')">Warm</button>\n            <button onclick="ppImgFilter(\'cool\')">Cool</button>\n            <button onclick="ppImgFilter(\'dramatic\')">Dramatic</button>\n            <button onclick="ppImgFilter(\'vivid\')">Vivid</button>\n          </div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Text Studio</h4>\n          <div class="pp-img-field"><label for="ppImgText">Text</label><input id="ppImgText" placeholder="Type your text"></div>\n          <div class="pp-img-field"><label for="ppImgTextSize">Size</label><input id="ppImgTextSize" type="number" min="8" max="500" value="64"></div>\n          <div class="pp-img-field"><label for="ppImgTextColor">Color</label><input id="ppImgTextColor" type="color" value="#ffffff"></div>\n          <div class="pp-img-field"><label for="ppImgTextOpacity">Opacity</label><output id="ppImgTextOpacityOut">100%</output><input id="ppImgTextOpacity" type="range" min="10" max="100" value="100" oninput="$(\'ppImgTextOpacityOut\').textContent=this.value+\'%\'"></div>\n          <div class="pp-img-tool-row">\n            <button onclick="ppImgAddText()">＋ Add Text</button>\n            <button onclick="ppImgAddWatermark()">Watermark</button>\n          </div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Shapes</h4>\n          <div class="pp-img-field"><label>Shape</label>\n            <select id="ppImgShapeType"><option value="rect">Rectangle</option><option value="circle">Circle</option><option value="line">Line</option></select>\n          </div>\n          <div class="pp-img-field"><label>Stroke</label><input id="ppImgShapeStroke" type="color" value="#ffffff"></div>\n          <div class="pp-img-field"><label>Fill</label><input id="ppImgShapeFill" type="color" value="#635bff"></div>\n          <div class="pp-img-field"><label>Stroke width</label><input id="ppImgShapeWidth" type="number" min="1" max="80" value="6"></div>\n          <div class="pp-img-tool-row"><button onclick="ppImgAddShape()">＋ Add Shape</button><button onclick="ppImgClearObjects()">Clear Objects</button></div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Drawing</h4>\n          <div class="pp-img-field"><label>Pen color</label><input id="ppImgPenColor" type="color" value="#ff3b30"></div>\n          <div class="pp-img-field"><label>Pen size</label><input id="ppImgPenSize" type="number" min="1" max="80" value="8"></div>\n          <div class="pp-img-tool-row"><button onclick="ppImgSetTool(\'pen\')" id="ppImgPenBtn">✏ Draw</button><button onclick="ppImgSetTool(\'select\')" id="ppImgSelectBtn">↖ Select</button></div>\n          <div class="pp-img-small-note">In Draw mode, drag directly on the image to create freehand strokes.</div>\n        </div>\n\n        <div class="tool-section">\n          <h4>Frame</h4>\n          <div class="pp-img-field"><label>Border color</label><input id="ppImgBorderColor" type="color" value="#ffffff"></div>\n          <div class="pp-img-field"><label>Border width</label><input id="ppImgBorderWidth" type="number" min="0" max="100" value="0"></div>\n          <button style="width:100%;margin-top:7px" onclick="ppImgApplyBorder()">Apply Border</button>\n        </div>\n\n      </aside>\n\n      <main class="pp-img-editor-canvas-stage">\n        <div class="pp-img-canvas-area">\n          <div class="pp-img-canvas-toolbar">\n            <button onclick="ppImgUndo()">↶ Undo</button>\n            <button onclick="ppImgRedo()">↷ Redo</button>\n            <button onclick="ppImgReset()">Reset</button>\n            <span class="pp-img-spacer"></span>\n            <button onclick="ppImgZoom(-0.1)">−</button>\n            <span id="ppImgZoomValue">100%</span>\n            <button onclick="ppImgZoom(0.1)">+</button>\n            <button onclick="ppImgFit()">Fit</button>\n          </div>\n\n          <div id="ppImgCanvasWrap" class="pp-img-canvas-wrap">\n            <div class="pp-img-empty">\n              <div class="pp-img-empty-icon">🖼️</div>\n              <b>Choose an image to start editing</b>\n              <span>Crop • Text • Shapes • Draw • Adjust • Filters • Export</span>\n            </div>\n            <canvas id="ppImgCanvas"></canvas>\n            <div id="ppImgCropBox" class="pp-img-crop-box"></div>\n          </div>\n\n          <div class="pp-img-bottom-bar">\n            <div><span>Image</span><b id="ppImgDimensions">—</b></div>\n            <div><span>Zoom</span><b id="ppImgZoomBottom">100%</b></div>\n            <div><span>Objects</span><b id="ppImgObjectCount">0</b></div>\n            <div><span>Status</span><b id="ppImgStatus">Ready</b></div>\n          </div>\n        </div>\n      </main>\n\n      <aside class="pp-img-export">\n        <h3>Export</h3>\n        <label>Format</label>\n        <select id="ppImgExportFormat">\n          <option value="image/jpeg">JPG</option>\n          <option value="image/png">PNG</option>\n          <option value="image/webp">WebP</option>\n        </select>\n        <label>Quality</label>\n        <input id="ppImgExportQuality" type="range" min="10" max="100" value="92" oninput="$(\'ppImgExportQualityOut\').textContent=this.value">\n        <output id="ppImgExportQualityOut">92</output>\n        <button class="primary pp-img-export-btn" onclick="ppImgExport()">Export Image</button>\n        <button class="secondary" onclick="ppImgReset()">Reset Editor</button>\n        <div class="pp-img-info"><b>Privacy</b><span>Editor operations are performed locally in your browser.</span></div>\n        <div class="pp-img-object-hint">Stage 2 adds real crop, text, shapes, drawing, watermark and border editing while keeping the existing PDF backend untouched.</div>\n      </aside>\n    </div>\n  </div>\n\n'
STAGE2_JS = "\nlet ppImgCanvas = null;\nlet ppImgCtx = null;\nlet ppImgSource = null;\nlet ppImgBaseCanvas = null;\nlet ppImgRotation = 0;\nlet ppImgFlipH = false;\nlet ppImgFlipV = false;\nlet ppImgZoomLevel = 1;\nlet ppImgHistory = [];\nlet ppImgHistoryIndex = -1;\nlet ppImgCurrentFilter = 'normal';\nlet ppImgObjects = [];\nlet ppImgTool = 'select';\nlet ppImgCropMode = false;\nlet ppImgCropRatio = null;\nlet ppImgCropStart = null;\nlet ppImgCropCurrent = null;\nlet ppImgBorder = {color:'#ffffff',width:0};\n\nfunction ppImgStudioTab(id,btn){\n  document.querySelectorAll('.pp-img-panel').forEach(x=>x.classList.add('hidden'));\n  const el=$(id);\n  if(el) el.classList.remove('hidden');\n  document.querySelectorAll('.pp-img-tab').forEach(x=>x.classList.remove('active'));\n  if(btn) btn.classList.add('active');\n}\n\nfunction ppImgInit(){\n  ppImgCanvas=$('ppImgCanvas');\n  ppImgCtx=ppImgCanvas.getContext('2d');\n  const input=$('ppImgEditorFile');\n  if(input) input.addEventListener('change',function(){\n    if(this.files && this.files[0]) ppImgLoadFile(this.files[0]);\n  });\n\n  if(ppImgCanvas){\n    ppImgCanvas.addEventListener('pointerdown',ppImgPointerDown);\n    ppImgCanvas.addEventListener('pointermove',ppImgPointerMove);\n    ppImgCanvas.addEventListener('pointerup',ppImgPointerUp);\n    ppImgCanvas.addEventListener('pointercancel',ppImgPointerUp);\n  }\n  ['ppImgBrightness','ppImgContrast','ppImgSaturation','ppImgBlur','ppImgSepia'].forEach(id=>{\n    const el=$(id);\n    if(el) el.addEventListener('change',ppImgCommitSettings);\n  });\n}\n\nfunction ppImgLoadFile(file){\n  const url=URL.createObjectURL(file);\n  const im=new Image();\n  im.onload=function(){\n    ppImgSource=im;\n    ppImgBaseCanvas=document.createElement('canvas');\n    ppImgBaseCanvas.width=im.naturalWidth;\n    ppImgBaseCanvas.height=im.naturalHeight;\n    ppImgBaseCanvas.getContext('2d').drawImage(im,0,0);\n    ppImgRotation=0; ppImgFlipH=false; ppImgFlipV=false; ppImgZoomLevel=1;\n    ppImgCurrentFilter='normal'; ppImgObjects=[]; ppImgBorder={color:'#ffffff',width:0};\n    ['ppImgBrightness','ppImgContrast','ppImgSaturation','ppImgBlur','ppImgSepia'].forEach(id=>{if($(id))$(id).value=0});\n    ppImgCropCancel();\n    ppImgHistory=[]; ppImgHistoryIndex=-1;\n    ppImgCanvas.style.display='block';\n    const empty=document.querySelector('#ppImgEditor .pp-img-empty');\n    if(empty) empty.style.display='none';\n    ppImgRender();\n    ppImgSaveHistory();\n    ppImgStatus('Image loaded');\n    URL.revokeObjectURL(url);\n  };\n  im.onerror=function(){ppImgStatus('Unable to read image');URL.revokeObjectURL(url)};\n  im.src=url;\n}\n\nfunction ppImgRender(){\n  if(!ppImgBaseCanvas || !ppImgCtx) return;\n  const srcW=ppImgBaseCanvas.width, srcH=ppImgBaseCanvas.height;\n  const swap=(Math.abs(ppImgRotation)%180)!==0;\n  const w=swap?srcH:srcW, h=swap?srcW:srcH;\n  ppImgCanvas.width=w; ppImgCanvas.height=h;\n\n  ppImgCtx.save();\n  ppImgCtx.clearRect(0,0,w,h);\n  ppImgCtx.translate(w/2,h/2);\n  ppImgCtx.rotate(ppImgRotation*Math.PI/180);\n  ppImgCtx.scale(ppImgFlipH?-1:1,ppImgFlipV?-1:1);\n\n  const b=Number($('ppImgBrightness')?.value||0);\n  const c=Number($('ppImgContrast')?.value||0);\n  const sat=Number($('ppImgSaturation')?.value||0);\n  const blur=Number($('ppImgBlur')?.value||0);\n  const sepia=Number($('ppImgSepia')?.value||0);\n  let filter=[];\n  if(b) filter.push('brightness('+(100+b)+'%)');\n  if(c) filter.push('contrast('+(100+c)+'%)');\n  if(sat) filter.push('saturate('+(100+sat)+'%)');\n  if(blur) filter.push('blur('+blur+'px)');\n  if(sepia) filter.push('sepia('+sepia+'%)');\n  if(ppImgCurrentFilter==='grayscale') filter.push('grayscale(100%)');\n  if(ppImgCurrentFilter==='sepia') filter.push('sepia(90%)');\n  if(ppImgCurrentFilter==='vintage') filter.push('sepia(35%) contrast(108%) saturate(82%)');\n  if(ppImgCurrentFilter==='warm') filter.push('sepia(15%) saturate(120%)');\n  if(ppImgCurrentFilter==='cool') filter.push('hue-rotate(12deg) saturate(88%)');\n  if(ppImgCurrentFilter==='dramatic') filter.push('contrast(125%) saturate(110%)');\n  if(ppImgCurrentFilter==='vivid') filter.push('contrast(112%) saturate(135%)');\n  ppImgCtx.filter=filter.length?filter.join(' '):'none';\n  ppImgCtx.drawImage(ppImgBaseCanvas,-srcW/2,-srcH/2);\n  ppImgCtx.restore();\n\n  ppImgCtx.save();\n  ppImgCtx.filter='none';\n  ppImgObjects.forEach(ppImgDrawObject);\n  if(ppImgBorder.width>0){\n    const bw=Math.min(ppImgBorder.width,Math.floor(Math.min(w,h)/8));\n    ppImgCtx.strokeStyle=ppImgBorder.color;\n    ppImgCtx.lineWidth=bw;\n    ppImgCtx.strokeRect(bw/2,bw/2,w-bw,h-bw);\n  }\n  ppImgCtx.restore();\n\n  ppImgCanvas.style.width=Math.min(100,Math.max(10,ppImgZoomLevel*100))+'%';\n  $('ppImgDimensions').textContent=w+'×'+h;\n  $('ppImgZoomValue').textContent=Math.round(ppImgZoomLevel*100)+'%';\n  $('ppImgZoomBottom').textContent=Math.round(ppImgZoomLevel*100)+'%';\n  if($('ppImgObjectCount')) $('ppImgObjectCount').textContent=ppImgObjects.length;\n  ppImgUpdateAdjustmentOutputs();\n}\n\nfunction ppImgUpdateAdjustmentOutputs(){\n  const pairs=[['ppImgBrightness','ppImgBrightnessOut'],['ppImgContrast','ppImgContrastOut'],['ppImgSaturation','ppImgSaturationOut'],['ppImgBlur','ppImgBlurOut'],['ppImgSepia','ppImgSepiaOut']];\n  pairs.forEach(([a,b])=>{if($(a)&&$(b))$(b).textContent=$(a).value});\n}\n\nfunction ppImgStatus(t){if($('ppImgStatus'))$('ppImgStatus').textContent=t}\n\nfunction ppImgRotate(deg){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  ppImgRotation=(ppImgRotation+deg+360)%360;\n  ppImgRender(); ppImgSaveHistory(); ppImgStatus('Rotated');\n}\nfunction ppImgFlip(axis){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  if(axis==='h')ppImgFlipH=!ppImgFlipH;else ppImgFlipV=!ppImgFlipV;\n  ppImgRender(); ppImgSaveHistory(); ppImgStatus('Flipped');\n}\nfunction ppImgApplyAdjustments(){\n  if(!ppImgBaseCanvas)return;\n  ppImgRender(); ppImgStatus('Adjusting');\n}\nfunction ppImgCommitSettings(){\n  if(!ppImgBaseCanvas)return;\n  ppImgRender(); ppImgSaveHistory(); ppImgStatus('Adjustment applied');\n}\nfunction ppImgFilter(name){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  ppImgCurrentFilter=name; ppImgRender(); ppImgSaveHistory();\n  ppImgStatus(name==='normal'?'Original filter':'Filter: '+name);\n}\n\nfunction ppImgSnapshot(){\n  return JSON.stringify({\n    pixels:ppImgBaseCanvas.toDataURL('image/png'),\n    rotation:ppImgRotation,flipH:ppImgFlipH,flipV:ppImgFlipV,\n    filter:ppImgCurrentFilter,\n    brightness:$('ppImgBrightness')?.value||0,\n    contrast:$('ppImgContrast')?.value||0,\n    saturation:$('ppImgSaturation')?.value||0,\n    blur:$('ppImgBlur')?.value||0,\n    sepia:$('ppImgSepia')?.value||0,\n    objects:ppImgObjects,\n    border:ppImgBorder\n  });\n}\nfunction ppImgSaveHistory(){\n  if(!ppImgBaseCanvas)return;\n  ppImgHistory=ppImgHistory.slice(0,ppImgHistoryIndex+1);\n  ppImgHistory.push(ppImgSnapshot());\n  ppImgHistoryIndex=ppImgHistory.length-1;\n  if(ppImgHistory.length>15){ppImgHistory.shift();ppImgHistoryIndex--}\n}\nfunction ppImgRestoreState(raw){\n  const x=JSON.parse(raw);\n  const im=new Image();\n  im.onload=function(){\n    ppImgBaseCanvas=document.createElement('canvas');\n    ppImgBaseCanvas.width=im.naturalWidth;ppImgBaseCanvas.height=im.naturalHeight;\n    ppImgBaseCanvas.getContext('2d').drawImage(im,0,0);\n    ppImgRotation=x.rotation||0;ppImgFlipH=!!x.flipH;ppImgFlipV=!!x.flipV;ppImgCurrentFilter=x.filter||'normal';\n    if($('ppImgBrightness'))$('ppImgBrightness').value=x.brightness;\n    if($('ppImgContrast'))$('ppImgContrast').value=x.contrast;\n    if($('ppImgSaturation'))$('ppImgSaturation').value=x.saturation;\n    if($('ppImgBlur'))$('ppImgBlur').value=x.blur;\n    if($('ppImgSepia'))$('ppImgSepia').value=x.sepia;\n    ppImgObjects=Array.isArray(x.objects)?x.objects:[];\n    ppImgBorder=x.border||{color:'#ffffff',width:0};\n    ppImgRender();\n  };\n  im.src=x.pixels;\n}\nfunction ppImgUndo(){\n  if(ppImgHistoryIndex<=0)return ppImgStatus('Nothing to undo');\n  ppImgHistoryIndex--;ppImgRestoreState(ppImgHistory[ppImgHistoryIndex]);ppImgStatus('Undo');\n}\nfunction ppImgRedo(){\n  if(ppImgHistoryIndex>=ppImgHistory.length-1)return ppImgStatus('Nothing to redo');\n  ppImgHistoryIndex++;ppImgRestoreState(ppImgHistory[ppImgHistoryIndex]);ppImgStatus('Redo');\n}\nfunction ppImgReset(){\n  if(!ppImgBaseCanvas)return;\n  const w=ppImgBaseCanvas.width,h=ppImgBaseCanvas.height;\n  ppImgRotation=0;ppImgFlipH=false;ppImgFlipV=false;ppImgCurrentFilter='normal';\n  ppImgObjects=[];ppImgBorder={color:'#ffffff',width:0};\n  ['ppImgBrightness','ppImgContrast','ppImgSaturation','ppImgBlur','ppImgSepia'].forEach(id=>{if($(id))$(id).value=0});\n  ppImgZoomLevel=1;ppImgCropCancel();ppImgRender();ppImgSaveHistory();ppImgStatus('Editor reset');\n}\nfunction ppImgZoom(delta){ppImgZoomLevel=Math.min(3,Math.max(.2,ppImgZoomLevel+delta));ppImgRender()}\nfunction ppImgFit(){ppImgZoomLevel=1;ppImgRender()}\n\nfunction ppImgSetTool(tool){\n  ppImgTool=tool;\n  if(tool!=='pen')ppImgCanvas.style.cursor='default';\n  else ppImgCanvas.style.cursor='crosshair';\n  if($('ppImgPenBtn'))$('ppImgPenBtn').classList.toggle('active',tool==='pen');\n  if($('ppImgSelectBtn'))$('ppImgSelectBtn').classList.toggle('active',tool==='select');\n  if(tool==='pen')ppImgStatus('Draw mode — drag on image');\n  else ppImgStatus('Select mode');\n}\n\nfunction ppImgSetCropRatio(r){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  ppImgCropRatio=r==='free'?null:(function(){\n    const q=r.split(':');return Number(q[0])/Number(q[1]);\n  })();\n  ppImgCropMode=true;ppImgTool='select';\n  ppImgCropStart=null;ppImgCropCurrent=null;\n  if(ppImgCanvas)ppImgCanvas.style.cursor='crosshair';\n  ppImgCropBoxShow(false);\n  ppImgStatus('Crop mode — drag on image');\n}\nfunction ppImgCropCancel(){\n  ppImgCropMode=false;ppImgCropStart=null;ppImgCropCurrent=null;\n  ppImgCropBoxShow(false);\n  if(ppImgCanvas)ppImgCanvas.style.cursor='default';\n}\nfunction ppImgCropToggle(){ppImgSetCropRatio('free')}\n\nfunction ppImgCanvasPoint(ev){\n  const r=ppImgCanvas.getBoundingClientRect();\n  return {\n    x:Math.max(0,Math.min(ppImgCanvas.width,(ev.clientX-r.left)*(ppImgCanvas.width/r.width))),\n    y:Math.max(0,Math.min(ppImgCanvas.height,(ev.clientY-r.top)*(ppImgCanvas.height/r.height)))\n  };\n}\nfunction ppImgPointerDown(ev){\n  if(!ppImgBaseCanvas)return;\n  if(ppImgCropMode){\n    ppImgCanvas.setPointerCapture(ev.pointerId);\n    ppImgCropStart=ppImgCanvasPoint(ev);ppImgCropCurrent=ppImgCropStart;\n    ppImgCropBoxUpdate();return;\n  }\n  if(ppImgTool==='pen'){\n    ppImgCanvas.setPointerCapture(ev.pointerId);\n    const p=ppImgCanvasPoint(ev);\n    ppImgObjects.push({type:'path',points:[p],color:$('ppImgPenColor')?.value||'#ff3b30',width:Number($('ppImgPenSize')?.value||8)});\n    ppImgRender();return;\n  }\n}\nfunction ppImgPointerMove(ev){\n  if(!ppImgBaseCanvas)return;\n  if(ppImgCropMode && ppImgCropStart){\n    ppImgCropCurrent=ppImgCanvasPoint(ev);ppImgCropBoxUpdate();return;\n  }\n  if(ppImgTool==='pen' && (ev.buttons&1)){\n    const p=ppImgCanvasPoint(ev);\n    const o=ppImgObjects[ppImgObjects.length-1];\n    if(o&&o.type==='path'){o.points.push(p);ppImgRender()}\n  }\n}\nfunction ppImgPointerUp(ev){\n  if(ppImgCropMode && ppImgCropStart){\n    ppImgCropCurrent=ppImgCanvasPoint(ev);ppImgCropBoxUpdate();\n    if(ev.pointerId!=null){try{ppImgCanvas.releasePointerCapture(ev.pointerId)}catch(e){}}\n  }else if(ppImgTool==='pen'){\n    if(ev.pointerId!=null){try{ppImgCanvas.releasePointerCapture(ev.pointerId)}catch(e){}}\n    ppImgSaveHistory();ppImgStatus('Drawing added');\n  }\n}\n\nfunction ppImgNormalizedCrop(){\n  if(!ppImgCropStart||!ppImgCropCurrent)return null;\n  let x=Math.min(ppImgCropStart.x,ppImgCropCurrent.x);\n  let y=Math.min(ppImgCropStart.y,ppImgCropCurrent.y);\n  let w=Math.abs(ppImgCropCurrent.x-ppImgCropStart.x);\n  let h=Math.abs(ppImgCropCurrent.y-ppImgCropStart.y);\n  if(ppImgCropRatio){\n    if(w/h>ppImgCropRatio)h=w/ppImgCropRatio;else w=h*ppImgCropRatio;\n  }\n  if(w<4||h<4)return null;\n  x=Math.max(0,Math.min(x,ppImgCanvas.width-w));\n  y=Math.max(0,Math.min(y,ppImgCanvas.height-h));\n  w=Math.min(w,ppImgCanvas.width-x);h=Math.min(h,ppImgCanvas.height-y);\n  return {x:Math.round(x),y:Math.round(y),w:Math.round(w),h:Math.round(h)};\n}\nfunction ppImgCropBoxShow(show){\n  const box=$('ppImgCropBox');if(!box)return;\n  box.style.display=show?'block':'none';\n}\nfunction ppImgCropBoxUpdate(){\n  const c=ppImgNormalizedCrop();const box=$('ppImgCropBox');if(!c||!box){ppImgCropBoxShow(false);return}\n  const cr=ppImgCanvas.getBoundingClientRect(),wr=$('ppImgCanvasWrap').getBoundingClientRect();\n  const sx=cr.width/ppImgCanvas.width,sy=cr.height/ppImgCanvas.height;\n  box.style.left=(cr.left-wr.left+c.x*sx)+'px';\n  box.style.top=(cr.top-wr.top+c.y*sy)+'px';\n  box.style.width=(c.w*sx)+'px';box.style.height=(c.h*sy)+'px';box.style.display='block';\n}\nfunction ppImgApplyCrop(){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  const c=ppImgNormalizedCrop();\n  if(!c)return ppImgStatus('Drag a crop area first');\n  ppImgRender();\n  const out=document.createElement('canvas');out.width=c.w;out.height=c.h;\n  out.getContext('2d').drawImage(ppImgCanvas,c.x,c.y,c.w,c.h,0,0,c.w,c.h);\n  ppImgBaseCanvas=out;\n  ppImgRotation=0;ppImgFlipH=false;ppImgFlipV=false;ppImgObjects=[];\n  ppImgCropCancel();ppImgRender();ppImgSaveHistory();ppImgStatus('Crop applied');\n}\n\nfunction ppImgDrawObject(o){\n  if(!o)return;\n  if(o.type==='text'){\n    ppImgCtx.save();ppImgCtx.globalAlpha=o.opacity;ppImgCtx.fillStyle=o.color;\n    ppImgCtx.font=(o.bold?'700 ':'')+o.size+'px '+o.font;\n    ppImgCtx.textAlign='center';ppImgCtx.textBaseline='middle';\n    ppImgCtx.translate(o.x,o.y);ppImgCtx.rotate((o.angle||0)*Math.PI/180);\n    ppImgCtx.fillText(o.text,0,0);ppImgCtx.restore();\n  }else if(o.type==='shape'){\n    ppImgCtx.save();ppImgCtx.lineWidth=o.width;ppImgCtx.strokeStyle=o.stroke;ppImgCtx.fillStyle=o.fill;\n    if(o.shape==='rect'){ppImgCtx.fillRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h);ppImgCtx.strokeRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h)}\n    else if(o.shape==='circle'){ppImgCtx.beginPath();ppImgCtx.arc(o.x,o.y,Math.min(o.w,o.h)/2,0,Math.PI*2);ppImgCtx.fill();ppImgCtx.stroke()}\n    else{ppImgCtx.beginPath();ppImgCtx.moveTo(o.x-o.w/2,o.y-o.h/2);ppImgCtx.lineTo(o.x+o.w/2,o.y+o.h/2);ppImgCtx.stroke()}\n    ppImgCtx.restore();\n  }else if(o.type==='path'){\n    if(!o.points.length)return;\n    ppImgCtx.save();ppImgCtx.strokeStyle=o.color;ppImgCtx.lineWidth=o.width;ppImgCtx.lineCap='round';ppImgCtx.lineJoin='round';\n    ppImgCtx.beginPath();ppImgCtx.moveTo(o.points[0].x,o.points[0].y);\n    for(let i=1;i<o.points.length;i++)ppImgCtx.lineTo(o.points[i].x,o.points[i].y);\n    ppImgCtx.stroke();ppImgCtx.restore();\n  }\n}\nfunction ppImgAddText(){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  const text=($('ppImgText')?.value||'').trim();if(!text)return ppImgStatus('Enter text first');\n  ppImgObjects.push({type:'text',text,x:ppImgCanvas.width/2,y:ppImgCanvas.height/2,size:Number($('ppImgTextSize')?.value||64),color:$('ppImgTextColor')?.value||'#ffffff',opacity:Number($('ppImgTextOpacity')?.value||100)/100,font:'Arial',bold:false,angle:0});\n  ppImgRender();ppImgSaveHistory();ppImgStatus('Text added');\n}\nfunction ppImgAddWatermark(){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  const text=($('ppImgText')?.value||'WATERMARK').trim();\n  ppImgObjects.push({type:'text',text,x:ppImgCanvas.width/2,y:ppImgCanvas.height/2,size:Number($('ppImgTextSize')?.value||64),color:$('ppImgTextColor')?.value||'#ffffff',opacity:.35,font:'Arial',bold:true,angle:-35});\n  ppImgRender();ppImgSaveHistory();ppImgStatus('Watermark added');\n}\nfunction ppImgAddShape(){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  const shape=$('ppImgShapeType')?.value||'rect';\n  ppImgObjects.push({type:'shape',shape,x:ppImgCanvas.width/2,y:ppImgCanvas.height/2,w:Math.max(80,ppImgCanvas.width*.32),h:Math.max(60,ppImgCanvas.height*.22),stroke:$('ppImgShapeStroke')?.value||'#ffffff',fill:$('ppImgShapeFill')?.value||'#635bff',width:Number($('ppImgShapeWidth')?.value||6)});\n  ppImgRender();ppImgSaveHistory();ppImgStatus('Shape added');\n}\nfunction ppImgClearObjects(){\n  if(!ppImgObjects.length)return ppImgStatus('No objects to clear');\n  ppImgObjects=[];ppImgRender();ppImgSaveHistory();ppImgStatus('Objects cleared');\n}\nfunction ppImgApplyBorder(){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  ppImgBorder={color:$('ppImgBorderColor')?.value||'#ffffff',width:Number($('ppImgBorderWidth')?.value||0)};\n  ppImgRender();ppImgSaveHistory();ppImgStatus(ppImgBorder.width?'Border applied':'Border removed');\n}\n\nfunction ppImgExport(){\n  if(!ppImgBaseCanvas)return ppImgStatus('Choose an image first');\n  ppImgRender();\n  const type=$('ppImgExportFormat').value||'image/jpeg';\n  const quality=Number($('ppImgExportQuality').value||92)/100;\n  ppImgCanvas.toBlob(function(blob){\n    if(!blob)return ppImgStatus('Export failed');\n    const ext=type==='image/png'?'png':type==='image/webp'?'webp':'jpg';\n    const a=document.createElement('a');a.href=URL.createObjectURL(blob);\n    a.download='PrivatePDF_edited_image.'+ext;document.body.appendChild(a);a.click();\n    setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);\n    ppImgStatus('Export complete');\n  },type,quality);\n}\n\nfunction ppImgPreset(w,h,name){\n  if($('imgWidth'))$('imgWidth').value=w;if($('imgHeight'))$('imgHeight').value=h;if($('imgMode'))$('imgMode').value='pixels';\n  ppImgStudioTab('ppImgResize',document.querySelector('.pp-img-tab:nth-child(2)'));st(name+' preset selected');\n}\nfunction ppImgPrintPreset(w,h,d,name){\n  if($('imgWidth'))$('imgWidth').value=w;if($('imgHeight'))$('imgHeight').value=h;if($('imgDpi'))$('imgDpi').value=d;\n  ppImgStudioTab('ppImgResize',document.querySelector('.pp-img-tab:nth-child(2)'));st(name+' print preset selected');\n}\nfunction ppImgCompressionInfo(){st('Compression settings ready — use Resize Pro for final export')}\n\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ppImgInit);else ppImgInit();\n\n"

